--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the GC keeps the tracker alive; a raw pointer here was
	// collected mid-game (see packaged crash in AddPoints).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "Null pointer dereference of ScoreTracker in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18), called from AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:38). ScoreTracker was created with NewObject<UArenaScoreTracker>(this) but stored in a raw pointer member without UPROPERTY, so it had no garbage-collection reference; the GC purged it mid-game (log: 'LogGarbage: Collecting garbage: 412 objects purged' at frame 3684) and the first goal scored after the collection dereferenced the dangling/null pointer (EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff). Fixed by making the member UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is not cooked into the packaged build: DefaultGame.ini has bCookAll=False and only cooks the map /Game/Maps/Arena plus /Game/Data/Effects, while the palette is loaded at runtime by code (LoadObject in ArenaGameMode::BeginPlay) and is not referenced by the map, so the cooker omits it. The packaged build then logs 'Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'Palette is null, using fallback gray', so the arena renders in the gray fallback instead of its colors. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to the packaging settings."
}
